// .debug_aranges (DWARF 2), as generated by the CW SmartLinker: one set per CU listing that CU's allocated sections.
import { ByteReader, ByteWriter } from '../util/bytes';

export interface ArangeSet {
  /** Offset of the CU in .debug_info. */
  infoOffset: number;
  addressSize: number;
  segmentSize: number;
  ranges: { address: number; length: number }[];
}

export function parseAranges(data: Uint8Array): ArangeSet[] {
  const out: ArangeSet[] = [];
  let off = 0;
  while (off + 4 <= data.length) {
    const r = new ByteReader(data, off);
    const len = r.u32();
    const end = off + 4 + len;
    r.u16(); // version
    const infoOffset = r.u32();
    const addressSize = r.u8();
    const segmentSize = r.u8();
    r.seek(off + Math.ceil((r.pos - off) / (2 * addressSize)) * 2 * addressSize);
    const ranges: ArangeSet['ranges'] = [];
    while (r.pos + 2 * addressSize <= end) {
      const address = r.uN(addressSize);
      const length = r.uN(addressSize);
      if (address === 0 && length === 0) break;
      ranges.push({ address, length });
    }
    out.push({ infoOffset, addressSize, segmentSize, ranges });
    off = end;
  }
  return out;
}

export function encodeAranges(sets: readonly ArangeSet[]): Uint8Array {
  const w = new ByteWriter(256);
  for (const s of sets) {
    const start = w.length;
    w.u32(0).u16(2).u32(s.infoOffset).u8(s.addressSize).u8(s.segmentSize);
    const tuple = 2 * s.addressSize;
    w.zeros(Math.ceil((w.length - start) / tuple) * tuple - (w.length - start));
    for (const r of s.ranges) w.uN(r.address, s.addressSize).uN(r.length, s.addressSize);
    w.zeros(tuple);
    w.setU32(start, w.length - start - 4);
  }
  return w.finish();
}
